UPDATE t_text_content t SET content=e.content FROM img_expected e WHERE t.id=e.tc_id;
UPDATE t_question q SET has_image=true FROM img_expected e WHERE q.id=e.id AND NOT q.is_golden;
DO $$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM t_question q JOIN img_expected e ON e.id=q.id WHERE q.has_image; IF n<>5 THEN RAISE EXCEPTION 'has_image应为5，实际%',n; END IF;
 SELECT count(*) INTO n FROM t_text_content t JOIN img_expected e ON e.tc_id=t.id WHERE t.content=e.content AND pg_input_is_valid(t.content,'json') AND position('/qimg/q'||e.id||'.jpg' in t.content)>0; IF n<>5 THEN RAISE EXCEPTION '内容更新应为5，实际%',n; END IF;
 SELECT count(*) INTO n FROM t_question q JOIN t_question_backup_20261118_imgpilot3 b ON b.id=q.id WHERE q.correct IS DISTINCT FROM b.correct; IF n<>0 THEN RAISE EXCEPTION '不应改答案%',n; END IF;
 SELECT count(*) INTO n FROM t_question q JOIN t_question_backup_20261118_imgpilot3 b ON b.id=q.id WHERE q.question_type IS DISTINCT FROM b.question_type; IF n<>0 THEN RAISE EXCEPTION '不应改题型%',n; END IF;
 SELECT count(*) INTO n FROM t_question WHERE NOT deleted; IF n<>44419 THEN RAISE EXCEPTION '活跃应为44419，实际%',n; END IF;
 SELECT count(*) INTO n FROM t_question WHERE is_golden; IF n<>200 THEN RAISE EXCEPTION '金标应为200，实际%',n; END IF;
END $$;
ROLLBACK;
